    /**
     * Tests getting all DataTasks.
     *
     * @return    Collection
     */
    public List<DataTask> testGetAll() throws Throwable {
    LOGGER.info( "DataTaskTest:testGetAll() - Retrieving Collection of DataTasks:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DataTask : " );
    List<DataTask> collection  = null;

    try {
        // call the static get method on the DataTaskService
        collection = service.getAllDataTask();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DataTask currEntity  = null;
            Iterator<DataTask> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDataTaskId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

